inline flight::Task<flight::Array<flight::Ref<flight::types::FileEntry>>> find_files(
    detail::HostFileSystem host_file_system, flight::String root_path, flight::String pattern,
    std::optional<detail::FileWalkOptions> options = std::nullopt) {
  auto all = co_await read_directory_recursive(host_file_system, root_path, options);
  if (all.empty()) co_return flight::Array<flight::Ref<flight::types::FileEntry>>{};
  const auto expression = detail::glob_to_reg_exp(pattern);
  co_return all.filter([expression](const flight::Ref<flight::types::FileEntry>& entry) {
    return expression.test(entry->name) || expression.test(entry->path);
  });
}

inline flight::String get_file_base_name(flight::String path) {
  const auto segments = detail::split_path(path);
  return segments.empty() ? flight::String() : segments.element(static_cast<double>(segments.size() - 1));
}

inline flight::String get_file_directory_name(flight::String path) {
  const auto segments = detail::split_path(path);
  return segments.size() <= 1 ? flight::String() : segments.slice(0, -1).join(flight::String("/"));
}

inline flight::String get_file_extension_name(flight::String path) {
  const auto base = get_file_base_name(path);
  const auto dot = base.last_index_of(flight::String("."));
  return dot > 0 ? base.slice(dot) : flight::String();
}

