inline bool is_absolute_file_path(flight::String path) {
  if (path.empty()) return false;
  if (path.char_at(0.0) == flight::String("/")) return true;
  return path.length() >= 2 && flight::RegExp(flight::String("^[A-Za-z]:")).test(path);
}

inline flight::String join_file_path(flight::Array<flight::String> segments) {
  const bool absolute = !segments.empty() && segments.element(0.0).starts_with(flight::String("/"));
  return detail::format_resolved_path(
      detail::resolve_path_segments(segments.join(flight::String("/")), absolute), absolute);
}

