inline flight::Task<bool> write_binary_file_chunks(
    detail::HostFileSystem host_file_system, flight::String path,
    flight::AsyncIterable<flight::Uint8Array> chunks,
    std::optional<flight::AbortSignal> signal = std::nullopt) {
  if (signal.has_value()) signal->throw_if_aborted();
  auto stream = co_await open_file_write_stream(host_file_system, path, signal);
  if (!stream.has_value()) co_return false;
  const auto writer = stream->get_writer();
  const auto ignore_rejection = [](const flight::Rejection&) {};
  if (signal.has_value() && signal->aborted) {
    co_await writer.abort(signal->reason.snapshot()).catch_error(ignore_rejection);
    signal->throw_if_aborted();
  }

  struct AbortState final {
    std::mutex mutex;
    bool aborted{false};
    std::optional<flight::Task<void>> abort_task;
  };
  const auto abort_state = std::make_shared<AbortState>();
  const flight::Function<void()> on_abort = [abort_state, writer, signal, ignore_rejection] {
    auto task = writer.abort(signal.has_value() ? signal->reason.snapshot() : flight::AbortReason{})
                    .catch_error(ignore_rejection);
    const std::scoped_lock lock(abort_state->mutex);
    abort_state->aborted = true;
    abort_state->abort_task = std::move(task);
  };
  if (signal.has_value()) {
    signal->add_event_listener(
        flight::String("abort"), on_abort, flight::AbortEventListenerOptions{.once = true});
  }

  bool succeeded = false;
  try {
    while (const auto chunk = co_await chunks.next()) {
      if (signal.has_value()) signal->throw_if_aborted();
      co_await writer.write(chunk->slice(0));
    }
    if (signal.has_value()) signal->throw_if_aborted();
    co_await writer.close();
    succeeded = true;
  } catch (...) {
    // The TypeScript catch deliberately converts non-abort stream failures to false.
  }

  bool aborted = false;
  std::optional<flight::Task<void>> abort_task;
  {
    const std::scoped_lock lock(abort_state->mutex);
    aborted = abort_state->aborted;
    abort_task = abort_state->abort_task;
  }
  if (!succeeded) {
    if (abort_task.has_value()) co_await abort_task.value();
    else co_await writer.abort().catch_error(ignore_rejection);
  }
  if (signal.has_value()) signal->remove_event_listener(flight::String("abort"), on_abort);
  if (succeeded) co_return true;
  if (aborted && signal.has_value()) signal->throw_if_aborted();
  co_return false;
}

